import {makeDraft,defaultSetup} from './fincheck-model';
export const evidenceCategories=['Front / back / side garment','Defect close-up & garment location','Selected carton & shipping marks','Barcode / price / hang / care labels','Carton dimensions & gross weight','Packing list','Lab test document','Metal detection record','Approved sample versus bulk'];
export function completeDraft(order,config={},setup=defaultSetup(),parent=null){const orderInfo=JSON.parse(JSON.stringify({...order,factory:order.factory||'',origin:order.origin||'',mode:order.mode||''}));const sizeBreakdown=(order.sizes||'').split('·').map(x=>x.trim().match(/^(\S+)\s+(\d+)$/)).filter(Boolean).map(x=>({colour:order.colour,size:x[1],qty:Number(x[2])}));return {...makeDraft(order,parent),schema:2,orderInfo,setup:{...setup},stage:config.stage||order.stage,productionPercent:'',packingPercent:'',packingListRef:'',readinessRef:'',skuDetails:(order.pos||[]).map(([po,qty])=>({po,qty,cartons:order.cartons,sku:'',colour:order.colour,exFactory:'',buyerDelivery:'',comment:''})),sizeBreakdown,attachments:[],checkEvidence:{},measurementTargets:{},measurementUnit:'in',...(config.external?{inspectionAgency:'',externalInspector:'',externalReportRef:'',externalResult:'PENDING'}:{})};}
export function evidenceUrl(a,moduleKey){if(!/^[a-f0-9]{24}$/.test(a.fileId||a.id||''))return null;return `/api/yqms/module-evidence?module=${encodeURIComponent(moduleKey)}&id=${a.fileId||a.id}`;}
