const Field=({label,children})=><label className="fip-field"><span>{label}</span>{children}</label>;
const NumberField=({label,value,onChange,min=0,max,step='1'})=><Field label={label}><input aria-label={label} type="number" min={min} max={max} step={step} value={value??''} onChange={e=>onChange(e.target.value)}/></Field>;
