 <nav className="fip-shortcuts" aria-label="Inspection form sections">{[['order','Order'],['scope','PO / sizes'],['sample','Sample'],['defects','Defects'],['measure','Measurements'],['checks','Checklist'],['evidence','Photos / files'],['hold','Hold / submit']].map(([id,label])=><button type="button" key={id} onClick={()=>jump(id)}>{label}</button>)}</nav>
